const independentLane=ref<IndependentLane|null>(null),independentCorrupt=ref(false)
const independentKey='companion.workflow-operation.independent.pending.v1'
function persistIndependent(value:IndependentLane){const target=storage();if(!target)throw Error('No independent pending store');target.setItem(independentKey,JSON.stringify(value));independentLane.value=value}
