const canChangeSourceGrant=computed(()=>{const r=record.value,b=sourcePolicies.value?.binding;if(!r||!b||!policiesBound.value)return false;if(b.state==='none')return !r.sourceGrant;if(b.state==='dynamic')return !!r.sourceGrant&&b.policyId===r.sourceGrant.policyId&&b.policyDigest===r.sourceGrant.policyDigest;return false})
