function validSourceGrant(r:WorkflowOperationRecord,id:string,p:NonNullable<ScopedPending['sourceGrant']>){return r.id===id&&r.revision>p.expectedRevision&&r.deliveryMode==='source-patch'&&r.sourceGrant?.policyId===p.policyId&&r.sourceGrant.policyDigest===p.policyDigest&&r.state==='draft'&&r.plan===null&&r.review===null&&r.activeRunId===null&&r.runs.length===0}
async function readSourcePolicies(){const item=record.value;if(!item||locked.value||isStale(item)||!props.provider.readSourcePolicies)return;busy.value='读取源码策略';sourcePolicyError.value='';sourcePolicies.value=null;sourcePolicyId.value='';sourcePolicyAgreed.value=false;try{const result=await props.provider.readSourcePolicies(item.id);if(selectedId.value!==item.id)return;if(result.workflowId!==item.id||result.projectId!==item.projectId||result.revision!==item.revision)throw Error('Policy binding changed');sourcePolicies.value=result}catch{if(selectedId.value===item.id)sourcePolicyError.value='源码策略读取未确认；请重新读取，不能据旧范围授权。'}finally{busy.value=''}}
async function grantSourcePolicy(){const item=record.value,policy=chosenSourcePolicy.value;if(!item||!policy||!policiesBound.value||!canChangeSourceGrant.value||!sourcePolicyAgreed.value||!props.provider.grantSourcePolicy||item.deliveryMode!=='source-patch'||item.activeRunId!==null||item.runs.length||!['draft','review','ready'].includes(item.state)||locked.value||isStale(item)||independentSelected.value||followupSelected.value)return;const grant={policyId:policy.id,policyDigest:policy.policyDigest,expectedRevision:item.revision},c=envelope(item);await command('授权源码范围',async operationId=>{const r=await props.provider.grantSourcePolicy!(item.id,{operationId,...grant});if(!validSourceGrant(r,item.id,grant))throw Error('Unconfirmed source grant');return r},c.operationId,grant);if(!pending.value&&record.value?.id===item.id&&record.value.sourceGrant?.policyId===grant.policyId){sourcePolicies.value=null;sourcePolicyId.value='';sourcePolicyAgreed.value=false;notice.value='源码范围已授权；原计划和审阅不再生效，请重新规划。'}}
const migrationMode=ref<WorkflowDeliveryMode|''>(''),migrationAgreed=ref(false)
function validMigrationResult(r:WorkflowOperationRecord,id:string,mode:WorkflowDeliveryMode){return r.id===id&&r.deliveryMode===mode&&r.state==='draft'&&r.plan===null&&r.review===null&&r.activeRunId===null&&r.runs.length===0}
async function migrateDeliveryMode(){const item=record.value,mode=migrationMode.value;if(!item||!mode||!migrationAgreed.value||!props.provider.changeDeliveryMode||item.deliveryMode!==undefined||item.activeRunId!==null||item.runs.length||!['draft','review','ready'].includes(item.state)||locked.value||isStale(item)||independentSelected.value||followupSelected.value)return;const c=envelope(item);await command(`设置交付方式:${mode}`,async operationId=>{const r=await props.provider.changeDeliveryMode!(item.id,{operationId,expectedRevision:item.revision,deliveryMode:mode});if(!validMigrationResult(r,item.id,mode)||r.revision<=item.revision)throw Error('Unconfirmed delivery mode');return r},c.operationId,undefined,{deliveryMode:mode,expectedRevision:item.revision});if(!pending.value&&record.value?.id===item.id&&record.value.deliveryMode===mode){migrationMode.value='';migrationAgreed.value=false;notice.value='交付方式已设置；原计划不再生效，请重新规划。'}}
function plan(){const item=record.value;if(!item||!['draft','review','ready'].includes(item.state))return;const c=envelope(item);void command('生成计划',()=>props.provider.generatePlan(item.id,c),c.operationId)}
async function review(){const item=record.value;if(!item?.plan||!canReview.value||!item.presentation?.planText)return;await readReadiness();if(selectedId.value!==item.id||!canReview.value)return;const c=envelope(item);await command('审阅计划',()=>props.provider.reviewPlan(item.id,{...c,selectedTaskId:selectedTaskId.value,sourceIds:[...selectedSourceIds.value],note:reviewNote.value.trim(),...(item.deliveryMode==='source-patch'?{patchPolicyDigest:sourcePolicies.value!.patchPolicy!.policyDigest}:{})}),c.operationId);if(!activePending.value&&selectedId.value===item.id)await readReadiness()}
async function start(){const item=record.value;if(!item||!canStart(item)||!readinessProofCurrent.value)return;await readReadiness();if(selectedId.value!==item.id||!readinessProofCurrent.value)return;const c=envelope(item);void command('提交启动请求',()=>props.provider.start(item.id,c),c.operationId)}
function pause(){const item=record.value;if(!item||!['running','queued'].includes(displayedState(item))||!activeRun(item)?.executionId)return;const c=envelope(item);void command('请求安全边界暂停',()=>props.provider.requestPause(item.id,c),c.operationId)}
async function readExecution(){const item=record.value;if(!item||busy.value)return;busy.value='查询执行状态';error.value='';try{details.value=await props.provider.readExecution(item.id);update(details.value.record)}catch{markStale(item.id);error.value='执行状态未读取成功，不能据此重跑或判定停止。'}finally{busy.value=''}}
function preparationMatches(row:PreparationRead){return !!record.value&&row.evidence.goalDigest===record.value.goal.digest&&(row.evidence.planDigest===null?row.evidence.phase==='plan':row.evidence.planDigest===record.value.plan?.digest)}
async function readPreparation(){const item=record.value;if(!item||busy.value||!props.provider.readPreparation)return;busy.value='读取准备调用证据';preparationError.value='';try{const result=await props.provider.readPreparation(item.id);if(selectedId.value!==item.id)return;preparation.value=result;preparationStale.value=false}catch{preparationStale.value=true;preparationError.value='准备调用证据读取失败；保留上次观察，不视为已采用。'}finally{busy.value=''}}

async function readApprovals(){const item=record.value;if(!item||busy.value||!props.provider.readApprovals)return;busy.value='读取当前会话审批';approvalError.value='';try{const result=await props.provider.readApprovals(item.id);if(selectedId.value!==item.id)return;approvals.value=result;approvalsStale.value=false;approvalClock.value=Date.now()}catch{approvalsStale.value=true;approvalError.value='审批读取失败；连接和能力未确认，不能批准或重发。'}finally{busy.value=''}}
async function decideApproval(item:WorkflowApproval,decision:'accept'|'decline'){
 const workflow=record.value;if(!workflow||!approvalActionable(item)||!props.provider.readApprovals||!props.provider.decideApproval)return
 const workflowId=workflow.id;busy.value='核对原会话待决请求';approvalError.value='';let live:WorkflowApproval|undefined
 try{const result=await props.provider.readApprovals(workflowId);if(selectedId.value!==workflowId)return;approvals.value=result;approvalsStale.value=false;approvalClock.value=Date.now();live=result.approvals.find(a=>a.id===item.id);if(!result.enabled||!live||live.version!==item.version||live.approvalDigest!==item.approvalDigest||live.connectionId!==item.connectionId||live.threadId!==item.threadId||live.turnId!==item.turnId||live.itemId!==item.itemId||live.state!=='pending'||!live.canRespond||Date.parse(live.expiresAt)<=approvalClock.value){approvalError.value='原请求已变化、失效或断线；没有发送决定，请重新核对。';return}}
 catch{approvalsStale.value=true;approvalError.value='未能核对原会话请求；没有发送决定。';return}finally{busy.value=''}
 if(!live)return;approvalsStale.value=true;const operationId=crypto.randomUUID();const target=live
