async function resume(){
 const item=record.value;if(!item||item.state!=='paused'||locked.value||!readinessProofCurrent.value)return
 await readReadiness();if(!readinessProofCurrent.value||selectedId.value!==item.id)return
 busy.value='恢复前核对';error.value='';let latest:WorkflowOperationRecord
 try{const read=await props.provider.readExecution(item.id);details.value=read;latest=read.record;update(latest)}catch{markStale(item.id);error.value='恢复前状态未确认，没有提交恢复。';return}finally{busy.value=''}
 if(latest.state!=='paused'||!activeRun(latest)?.executionId){notice.value='最新状态不允许恢复，没有重发已完成动作。';return}
 const c=envelope(latest);void command('恢复同一执行',()=>props.provider.resume(latest.id,c),c.operationId)
}
watch(()=>[record.value?.id,record.value?.revision],()=>{recoveryPreview.value=null;recoveryPreviewError.value='';})
async function readRecoveryPreflight(){
 const item=record.value;if(!item||busy.value||!props.provider.readRecoveryPreflight)return;
 const revision=item.revision;busy.value='读取恢复条件';recoveryPreview.value=null;recoveryPreviewError.value='';
 try{const result=await props.provider.readRecoveryPreflight(item.id);if(record.value?.id!==item.id||record.value.revision!==revision||result.revision!==revision)throw Error('STALE_PREFLIGHT');recoveryPreview.value=result;}
 catch{recoveryPreviewError.value='恢复条件读取失败或状态已变化；未发送处置，请刷新后重新读取。';}finally{busy.value=''}
}
const planningRecoveryMessage=ref('')
watch(()=>record.value?.id,()=>{planningRecoveryMessage.value=''})
async function recoverPlanningTransport(){
 const item=record.value,operationId=item?.planningConversation?.requestId;if(!item||!operationId||!item.plan||busy.value||!props.provider.recoverPlanningTransport)return;
 busy.value='核查规划连接';planningRecoveryMessage.value='正在只读核查原规划连接…';
 try{const result=await props.provider.recoverPlanningTransport(item.id,{operationId,expectedRevision:item.revision});if(result.workflowId!==item.id||result.originalOperationId!==operationId)throw Error('Recovery identity mismatch');if(record.value?.id===item.id)planningRecoveryMessage.value='已核实系统重启后的原规划连接，原记录和预算保留；未重新规划或启动执行。';}
 catch(cause){if(record.value?.id===item.id){const code=cause instanceof WorkflowCommandError?cause.code:undefined;planningRecoveryMessage.value=code==='CODEX_VERSION_NOT_APPROVED'?'本机 Codex 版本尚未登记为可信版本，核查进程未派发；原记录和预算保留。':`规划连接核查未通过${code?'（'+code+'）':''}；原记录和预算保留，未重新规划或启动执行。`;}}finally{busy.value='';}
}
async function abandonBeforeTurn(){
 const item=record.value,original=item?activeRun(item):undefined;if(!item||item.state!=='unknown'||!original||busy.value||isStale(item)||!recoveryPreview.value?.canRequestVerification||recoveryPreview.value.revision!==item.revision||!props.provider.abandonBeforeTurn)return;
 busy.value='核对未派发证据';error.value='';
 try{update(await props.provider.abandonBeforeTurn(item.id,{operationId:original.operationId,expectedRevision:item.revision}));notice.value='已按服务端证据追加放弃处置；原 UNKNOWN 审计保留。'}
 catch{markStale(item.id);recoveryPreview.value=null;error.value='恢复证据不足或提交结果未确认；保留 UNKNOWN，请读取原目标状态，不自动重试。'}finally{busy.value=''}
}
async function findServerRequest(){const item=record.value;if(!item||busy.value||pending.value||pendingCorrupt.value||!props.provider.listRequestIngress)return;busy.value='查找服务端请求';try{const rows=await props.provider.listRequestIngress(item.id),candidates=[] as typeof rows;for(const row of rows){if(!['plan','review','start','pause','resume','accept','delivery-mode','source-grant'].includes(row.kind)||row.state==='rejected')continue;if(row.state==='settled'){const op=await props.provider.getOperation(row.operationId,item.id);if(op.state==='settled')continue}candidates.push(row)}const scoped=candidates.filter(row=>['delivery-mode','source-grant'].includes(row.kind)&&['pending','unknown'].includes(row.state));if(scoped.length){if(scoped.length>256)throw Error('Too many unresolved requests');const request:ScopedPending={operationId:scoped[0].operationId,workflowId:item.id,kind:'服务器待核请求',serverRequests:scoped.map(row=>({operationId:row.operationId,kind:row.kind as 'delivery-mode'|'source-grant',state:row.state as 'pending'|'unknown'}))};const st=storage();if(!st||pending.value)throw Error();savePending(request);if(readScopedPending(st)[item.id]?.operationId!==request.operationId)throw Error();pending.value=request;notice.value='发现服务器未确认请求；原始参数不在本会话，保持锁定，请保留原会话，不猜测或重发。';return}if(candidates.length===0){const refused=rows.filter(row=>row.state==='rejected');if(refused.length){notice.value='已记录的拒绝：'+refused.slice(-3).map(row=>`${row.operationId}${row.code?`（${row.code}）`:''}`).join('、')+'。';return}}if(candidates.length!==1)throw Error();const row=candidates[0],request={operationId:row.operationId,workflowId:item.id,kind:row.kind};const st=storage();if(!st||pending.value)throw Error();savePending(request);if(readScopedPending(st)[item.id]?.operationId!==request.operationId)throw Error();pending.value=request;notice.value='已找回唯一的服务端待核请求；不会自动重发。'}catch{error.value='未能唯一核对服务端请求；没有更改原记录。'}finally{busy.value=''}}
async function reconcile(){if(!pending.value||busy.value)return;const request={...pending.value};if(request.kind==='服务器待核请求'){notice.value='原始参数不在本会话，无法核验请求绑定；请保留原会话，继续锁定，不猜测或重发。';return}busy.value='查询请求结果';error.value='';try{const result=await props.provider.getOperation(request.operationId,request.workflowId);if(result.operationId!==request.operationId||(result.record&&result.record.id!==result.workflowId)||(request.workflowId&&result.workflowId&&request.workflowId!==result.workflowId))throw Error();if(request.kind==='授权源码范围'&&result.state==='settled'&&result.outcome!=='not-dispatched'&&(!request.workflowId||!request.sourceGrant||!result.record||!validSourceGrant(result.record,request.workflowId,request.sourceGrant)))throw Error('Unconfirmed source grant');if(request.kind.startsWith('设置交付方式:')&&result.state==='settled'&&result.outcome!=='not-dispatched'){const mode=request.kind.slice('设置交付方式:'.length);if(!request.workflowId||!['sample','source-patch'].includes(mode)||!result.record||!validMigrationResult(result.record,request.workflowId,mode as WorkflowDeliveryMode))throw Error('Unconfirmed delivery mode')}if(result.record)update(result.record);if(result.state==='settled'&&result.record){clearPending(false,false,request);if(commandFeedback.value?.operationId===request.operationId&&commandFeedback.value.workflowId===request.workflowId)commandFeedback.value=null;notice.value='已读取该请求结果，未重新提交。';if(result.outcome==='not-dispatched')notice.value='原请求已确认未派发；原回执保留，不代表执行成功。'}else if(result.state==='not-observed'&&request.workflowId&&props.provider.readIngressProof&&(request.kind==='授权源码范围'||request.kind.startsWith('设置交付方式:'))){const kind=request.kind==='授权源码范围'?'source-grant':'delivery-mode';const metadata=kind==='source-grant'?request.sourceGrant:request.modeChange;if(!metadata)throw Error('Missing pending request binding');const input:Record<string,string|number>=kind==='source-grant'?{operationId:request.operationId,expectedRevision:request.sourceGrant!.expectedRevision,policyId:request.sourceGrant!.policyId,policyDigest:request.sourceGrant!.policyDigest}:{operationId:request.operationId,expectedRevision:request.modeChange!.expectedRevision,deliveryMode:request.modeChange!.deliveryMode};const digest=await ingressRequestDigest(request.workflowId,kind,input);const proof=await props.provider.readIngressProof(request.workflowId,request.operationId);if(proof.workflowId!==request.workflowId||proof.operationId!==request.operationId)throw Error('Ingress identity mismatch');if(proof.state==='rejected'){if(proof.kind!==kind||proof.requestDigest!==digest)throw Error('Ingress request mismatch');clearPending(false,false,request);notice.value='原请求经后端核对已明确拒绝，未重新提交；可核对原因后重新操作。'}else notice.value='原请求尚未证实拒绝，保持写入锁定，不自动重发。'}else if(result.state==='not-observed'&&request.workflowId&&props.provider.readRequestIngress){const ingress=await props.provider.readRequestIngress(request.workflowId,request.operationId);const detail=ingress.code&&/^[A-Z][A-Z0-9_]{1,99}$/.test(ingress.code)?`（${ingress.code}）`:'';notice.value=`服务端请求状态 ${ingress.state}${detail}；保持写入锁定，不自动重发。`}else notice.value='该请求结果仍未确认，保持写入锁定，不自动重发。'}catch{error.value='请求结果读取失败，继续保留原操作标识。'}finally{busy.value=''}}
const formalRun=computed(()=>record.value?taskDirectoryRun(record.value):undefined)
const acceptanceScope=computed(()=>formalRun.value?'task-directory':run.value?.capability==='restricted-readonly-model-output'?'technical-sample':'unverified')
const patchInspection=ref<import('./workflow-operation').SourcePatchInspection|null>(null),patchInspectionRevision=ref<number|null>(null),patchInspectionError=ref('')
const patchInspectionCurrent=computed(()=>{const v=patchInspection.value,r=record.value,n=approvalClock.value;if(!v||!r||r.deliveryMode!=='source-patch'||r.revision!==patchInspectionRevision.value||r.id!==v.workflowId||r.activeRunId!==v.runId||r.goal.digest!==v.goalDigest||r.plan?.digest!==v.planDigest||r.review?.patchPolicyDigest!==v.policyDigest||v.state!=='passed')return false;const age=n-Date.parse(v.observedAt);return Number.isFinite(age)&&age>=0&&age<=60000})
async function readPatchInspection(){const item=record.value;if(!item||item.deliveryMode!=='source-patch'||busy.value)return;patchInspection.value=null;patchInspectionRevision.value=null;patchInspectionError.value='';if(!props.provider.readSourcePatchInspection){patchInspectionError.value='当前服务未接入补丁检查。';return}busy.value='核对源码补丁';try{const result=await props.provider.readSourcePatchInspection(item.id);if(selectedId.value!==item.id)return;const latest=record.value;if(!latest||latest.revision!==item.revision||result.workflowId!==item.id||result.runId!==item.activeRunId||result.goalDigest!==item.goal.digest||result.planDigest!==item.plan?.digest||result.policyDigest!==item.review?.patchPolicyDigest||result.state!=='passed'||result.validity!=='point-in-time'||result.activity!=='unverified'||result.tests!=='not-verified'||result.applied!=='unverified'||result.accepted!==false)throw Error('Inspection binding changed');patchInspection.value=result;patchInspectionRevision.value=item.revision;approvalClock.value=Date.now()}catch{if(selectedId.value===item.id)patchInspectionError.value='补丁检查失败或结果未知；请重新核对。'}finally{busy.value=''}}
function accept(){const item=record.value;if(acceptanceScope.value==='unverified'||!item||item.deliveryMode==='source-patch'&&!patchInspectionCurrent.value||item.state!=='completed'||!details.value||!acceptanceNote.value.trim()||!selectedEvidence.value.length||locked.value)return;const c=envelope(item);void command('提交验收',()=>props.provider.accept(item.id,{...c,evidenceDigests:[...selectedEvidence.value],note:acceptanceNote.value.trim()}),c.operationId)}
const viewedPlanTaskId=ref('')
function selectPlanTask(id:string,taskId:string){if(selectedId.value!==id)select(id);viewedPlanTaskId.value=taskId}
function select(id:string){viewedPlanTaskId.value='';migrationMode.value='';migrationAgreed.value=false;sourcePolicies.value=null;sourcePolicyId.value='';sourcePolicyAgreed.value=false;sourcePolicyError.value='';resetReadiness();approvals.value=null;approvalsStale.value=false;approvalError.value='';preparation.value=null;preparationStale.value=false;preparationError.value='';selectedId.value=id;details.value=null;acceptanceNote.value='';selectedEvidence.value=[];persistRecordRoute()}
function selectWorkflow(id:string):boolean{if(!visibleRecords.value.some(item=>item.id===id))return false;select(id);return true}
defineExpose({refresh,selectWorkflow})
let autoReadTimer:ReturnType<typeof setInterval>|undefined
async function autoRead(){if(busy.value)return;await refresh();if(pending.value&&!busy.value)await reconcile();if(sameDraftPending.value&&!createSubmitting.value)await queryGoalDraft()}
onMounted(()=>{autoReadTimer=setInterval(()=>void autoRead(),15000);restorePending();restoreTrackingPending();restoreIndependent();restoreFollowup();restoreContinuation();restoreLost();restoreSettlement();restorePrewrite();restoreAdvanceResolution();restoreFinishPending();void refresh();approvalClockTimer=setInterval(()=>{approvalClock.value=Date.now()},1000)})
onBeforeUnmount(()=>{if(autoReadTimer)clearInterval(autoReadTimer);if(approvalClockTimer)clearInterval(approvalClockTimer)})
</script>
<template>
 <section class="workflow-operation" aria-labelledby="workflow-operation-title">
  <header><h2 id="workflow-operation-title">{{ !section?'目标与执行':section==='goals'?'创建与管理目标':section==='specs'?'计划与版本审阅':section==='tasks'?'任务详情':section==='execution'?'执行与日志':section==='acceptance'?'执行验收':'准备调用证据' }}</h2><div><el-button v-if="showSection('goals')" :disabled="createSubmitting" @click="newGoalForm">新建目标</el-button><el-button :disabled="!!busy" @click="refresh">读取最新状态</el-button></div></header>
  <section v-if="showSection('execution')&&record" aria-label="结束未通过验收的追踪"><template v-if="record.independentChannel"><p role="status">旧目标未通过验收，子活动未验证；原目录保持隔离。独立目标 {{ record.independentChannel.newGoalId }}。</p></template><template v-else-if="provider.createIndependentChannelGoal&&independentSelected&&record.state==='completed'&&run?.state==='completed'&&!run.acceptance&&!record.finishedDisposition"><button type="button" :disabled="!!busy||isStale(record)||!!followupPending||!!followupLane||followupCorrupt||!!finishPending" data-testid="channel-open" @click="channelOpen=true">建立独立目标通道（子活动未验证）</button><div v-if="channelOpen"><p>旧目标未通过验收，子活动未验证。旧活动可能争用目录以外的资源；原目录、记录和旧锁保持隔离。</p><label>新目标名称<input data-testid="channel-title" v-model="channelTitle" maxlength="160"></label><label>新目标内容<textarea data-testid="channel-description" v-model="channelDescription" maxlength="8000"></textarea></label><label>输入原执行请求标识<input data-testid="channel-typed" v-model="channelTyped" autocomplete="off"></label><label><input type="checkbox" data-testid="channel-agreed" v-model="channelAgreed">我接受上述风险，且仅创建新的独立目标。</label><button type="button" :disabled="!!busy||!channelAgreed||channelTyped!==run.operationId||!channelTitle.trim()||!channelDescription.trim()" data-testid="channel-submit" @click="openIndependentChannel">确认建立独立通道并创建目标</button><button type="button" :disabled="!!busy" @click="channelOpen=false">返回</button></div></template><section v-if="followupPending" role="status">独立通道结果待核对，旧目录保持隔离。<button type="button" :disabled="!!busy" data-testid="channel-reconcile" @click="reconcileFollowupCreation">查询独立通道结果</button></section><section v-if="followupLane?.pending" role="status">新目标请求待核对。<button type="button" :disabled="!!busy" @click="reconcileFollowupAction">查询新目标请求</button></section><p v-if="followupCorrupt" role="alert">通道记录不可读，保持锁定。</p><template v-if="record.finishedDisposition"><p role="status">已结束追踪，未通过验收；原执行证据和任务目录仍隔离。</p></template><template v-else-if="provider.finishUnaccepted&&independentSelected&&record.state==='completed'&&run?.state==='completed'&&!run.acceptance"><button type="button" :disabled="!!busy||isStale(record)||!!finishPending||finishCorrupt" @click="finishConfirm=true">保留结果并结束追踪（未通过验收）</button><div v-if="finishConfirm"><p>只记录未通过验收，保留原目录和审计；不取消执行，不恢复旧任务。</p><label>输入原执行请求标识<input v-model="finishTyped" autocomplete="off"></label><button type="button" :disabled="!!busy||finishTyped!==run.operationId" @click="finishUnaccepted">确认结束追踪</button><button type="button" :disabled="!!busy" @click="finishConfirm=false">返回</button></div></template><section v-if="finishPending" role="status">处置回执待核对，通道保持锁定。<button type="button" :disabled="!!busy" @click="reconcileFinished">查询收尾回执</button></section><p v-if="finishCorrupt" role="alert">收尾记录不可读，通道保持锁定。</p></section>
  <section v-if="showSection('execution')&&record" aria-label="后续独立目标"><button v-if="provider.listRequestIngress" type="button" data-testid="find-server-request" :disabled="!!busy||!!pending||pendingCorrupt" @click="findServerRequest">查找本目标服务端请求</button><template v-if="continuationAnchor&&provider.advanceIndependentChannel"><button type="button" data-testid="continuation-open" :disabled="!!busy||!!continuationPending||continuationCorrupt||!!lostPending||lostCorrupt||!!followupPending||!!followupLane?.pending" @click="continueOpen=true">完成已验收通道并建立后续目标</button><div v-if="continueOpen"><p>原任务子活动仍未验证，可能争用目录外资源；原记录和目录继续隔离。</p><label>新目标名称<input data-testid="continuation-title" v-model="continueTitle" maxlength="160"></label><label>新目标内容<textarea data-testid="continuation-description" v-model="continueDescription" maxlength="8000"></textarea></label><label>输入已验收执行请求标识<input data-testid="continuation-typed" v-model="continueTyped"></label><label><input type="checkbox" data-testid="continuation-agreed" v-model="continueAgreed">我接受旧子活动未验证的风险，仅建立此独立目标。</label><button type="button" data-testid="continuation-submit" :disabled="!!busy||!!continuationPending||continuationCorrupt||!continueAgreed||continueTyped!==run?.operationId||!continueTitle.trim()||!continueDescription.trim()" @click="continueChannel">确认建立后续目标</button><button type="button" @click="continueOpen=false">返回</button></div></template><button v-if="serverIntentAnchor&&provider.listContinuationIntents" type="button" data-testid="server-intent-query" :disabled="!!busy||!!continuationPending||!!lostPending||continuationCorrupt||lostCorrupt" @click="recoverServerContinuation">查找服务端待核请求</button><template v-if="continuationAnchor&&provider.readLostBarrierPreview&&provider.recordLostBarrier"><button type="button" data-testid="lost-preview" :disabled="!!busy||!!continuationPending||!!lostPending||lostCorrupt" @click="previewLost">核对编号丢失的未知请求</button><div v-if="lostOpen"><p>原编号丢失、结果仍未知且不重发；原目录和审计继续隔离。本操作只记录屏障，不创建新目标。</p><label><input type="checkbox" data-testid="lost-agreed" v-model="lostAgreed">确认记录未知结果并保留原隔离。</label><button type="button" data-testid="lost-submit" :disabled="!!busy||!lostAgreed||!!lostPending||lostCorrupt" @click="recordLost">记录未知结果屏障</button></div></template><section v-if="lostPending&&record.id===lostPending.anchorId&&provider.settleOriginalBarrierUnknown" aria-label="原请求收尾"><button type="button" data-testid="settlement-preview" :disabled="!!busy||!!settlementPending||settlementCorrupt" @click="previewOriginalSettlement">核对原请求收尾</button><div v-if="settlementPreview"><p>只收尾原请求 {{ lostPending.operationId }}；历史结果仍未知、禁止重发，原目录保持隔离。</p><label><input type="checkbox" data-testid="settlement-agreed" v-model="settlementAgreed">确认保留未知结果和原目录隔离。</label><button type="button" data-testid="settlement-submit" :disabled="!!busy||!settlementAgreed||!!settlementPending||settlementCorrupt" @click="submitOriginalSettlement">确认收尾原请求</button></div></section><section v-if="settlementPending&&provider.reconcilePrewriteFailure&&settlementPending.operationId==='1a225d29-50d8-43bc-87d5-18acaabc8383'" aria-label="核对写入前异常"><p>仅核对已记录的写入前基线异常；原请求仍未知，原目录保持隔离。</p><label><input type="checkbox" data-testid="prewrite-agreed" v-model="prewriteAgreed">确认保留原未知记录，不重发原请求。</label><button type="button" data-testid="prewrite-submit" :disabled="!!busy||!prewriteAgreed||prewritePending||prewriteCorrupt" @click="reconcilePrewrite">核对这次写入前异常</button><button v-if="prewritePending" type="button" data-testid="prewrite-query" :disabled="!!busy" @click="queryPrewriteResolution">查询核对结果</button><p v-if="prewriteCorrupt" role="alert">核对记录不可读，已停止。</p></section><section v-if="settlementPending" role="status">收尾请求 {{ settlementPending.operationId }} 待核对，不自动重发。<button type="button" data-testid="settlement-query" :disabled="!!busy" @click="queryOriginalSettlement">查询收尾请求</button></section><p v-if="settlementCorrupt" role="alert">收尾记录不可读，已停止提交。</p><section v-if="lostPending" role="status">屏障待核对，不自动重发。请求编号：{{ lostPending.operationId }}。<button type="button" :disabled="!!busy" @click="queryLost">查询屏障结果</button></section><p v-if="lostCorrupt" role="alert">屏障记录不可读，保持锁定。</p><section v-if="continuationPending?.operationId==='09f57950-b742-49f9-b9cb-5d8a479187e1'&&provider.reconcileAdvancePrewriteFailure" aria-label="核对09f写入前异常"><p>仅核对09f写入前异常；原intent与ingress保留unknown，禁止重发原请求。</p><label><input data-testid="advance-prewrite-agreed" type="checkbox" v-model="advanceResolveAgreed">确认保留原未知记录与审计，仅追加有据核对</label><button data-testid="advance-prewrite-submit" :disabled="!!busy||!advanceResolveAgreed||advanceResolvePending||advanceResolveCorrupt" @click="reconcileAdvancePrewrite">核对09f写入前异常</button><button v-if="advanceResolvePending" data-testid="advance-prewrite-query" :disabled="!!busy" @click="queryAdvanceResolution">查询09f核对结果</button><p v-if="advanceResolveCorrupt" role="alert">09f核对本地记录不可读，停止。</p></section>
<section v-if="continuationPending" role="status">后续通道待核对，不自动重发。请求编号：{{ continuationPending.operationId }}。<button type="button" :disabled="!!busy" @click="reconcileContinuation">查询后续通道结果</button></section><p v-if="continuationCorrupt" role="alert">后续通道记录不可读，保持锁定。</p></section>
  <section v-if="showSection('execution')&&record?.state==='unknown'" aria-label="停止追踪处置">
   <template v-if="record.tracking"><p role="status">已停止追踪，结果仍为 UNKNOWN。停止追踪不等于取消执行；目录 {{ record.tracking.directoryRelativePath }} 仍隔离，不允许重发或复用。</p><p>处置 {{ record.tracking.dispositionId }} · {{ record.tracking.at }} · 迟到回执 {{ record.tracking.lateObservationCount }} 条，单独留证。</p></template>
   <template v-else-if="provider.stopTracking&&run?.state==='unknown'"><el-button data-testid="open-stop-tracking" :disabled="!!busy||isStale(record)||!!trackingPending||trackingCorrupt||pendingCorrupt" @click="openTrackingConfirmation">停止追踪，保留未知结果</el-button><p>此操作不会取消执行、释放目录或证明未派发，也不会授权终止未知进程。</p></template>
   <div v-if="trackingTarget" role="group" aria-label="确认具体停止追踪目标"><p>目标 {{ trackingTarget.id }} · 修订 {{ trackingTarget.revision }} · 原操作 {{ trackingTarget.originalOperationId }}</p><label>输入原操作标识确认目标<input data-testid="tracking-original-id" v-model="trackingTyped" :disabled="!!busy" autocomplete="off"></label><label><input data-testid="tracking-agree" type="checkbox" v-model="trackingAgreed" :disabled="!!busy">我确认仅停止追踪；结果仍未知，目录保持隔离，维护另行核对当前活动。</label><el-button data-testid="confirm-stop-tracking" :disabled="!!busy||!trackingAgreed||trackingTyped!==trackingTarget.originalOperationId" @click="stopTracking">确认仅停止追踪此目标</el-button><el-button :disabled="!!busy" @click="trackingTarget=null">返回</el-button></div>
   <div v-if="trackingPending" role="status">待核对处置 {{ trackingPending.operationId }} · 目标 {{ trackingPending.workflowId }}<el-button data-testid="reconcile-stop-tracking" :disabled="!!busy" @click="reconcileTracking">查询该处置结果</el-button><p>原执行请求和未知结果仍保留，不自动重发。</p></div><p v-if="trackingCorrupt" role="alert">本地处置记录不可读，禁止重复提交。</p>
  </section>
  <details class="metadata"><summary>执行范围说明</summary><p>执行范围由后端任务策略及真实回执确认；本页不授予工程路径或仓库权限。</p></details>
  <p v-if="run?.capability==='restricted-readonly-model-output'" class="metadata">此执行为只读技术样例；历史结果不会升级为正式工程验收。</p>
  <p v-if="busy" role="status"><el-icon class="is-loading"><Loading/></el-icon>{{ busy }}；受理不等于执行成功。</p>
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><el-alert v-if="commandFeedback&&(!commandFeedback.workflowId||commandFeedback.workflowId===selectedId)" :title="commandFeedback.message" type="error" show-icon @close="commandFeedback=null"/>
  <el-alert v-if="pendingCorrupt" title="待核对请求记录不可读，写入保持锁定；请先核对原请求，不自动清除。" type="warning" :closable="false" show-icon/>
  <el-alert v-if="notice" :title="notice" type="info" :closable="false" show-icon/>
  <div v-if="pending" class="pending-command" role="status"><strong>待核对请求</strong><p>{{ pending.kind }} · {{ pending.operationId }}</p><ul v-if="pending.serverRequests"><li v-for="entry in pending.serverRequests" :key="entry.operationId">{{ entry.kind }} · {{ entry.operationId }} · {{ entry.state==='pending'?'待确认':'结果未知' }}</li></ul><p v-if="pending.serverRequests">缺少原始请求参数；请保留原会话，不能猜测或重发。</p><el-button :disabled="!!busy" @click="reconcile">查询该请求结果</el-button><p>不会自动重发，也不允许创建新请求绕过未知结果。</p></div>
  <section v-if="independentLane?.pending" aria-label="独立目标待核对请求"><p>{{ independentLane.pending.kind }} · {{ independentLane.pending.operationId }}；旧请求未覆盖。</p><el-button :disabled="!!busy" @click="reconcileIndependent">查询独立请求结果</el-button></section>
  <el-dialog v-model="creating" title="新建目标" class="workflow-goal-dialog" align-center :close-on-click-modal="false" :close-on-press-escape="!createSubmitting" :show-close="!createSubmitting" width="min(680px, 92vw)"><form v-if="creating" id="workflow-goal-form" aria-label="新建目标" @submit.prevent="saveGoalDraft">
   <label for="workflow-goal-title">需求名称</label><input id="workflow-goal-title" v-model="draftTitle" maxlength="160" required :disabled="draftFrozen"><label for="workflow-goal-description">需求内容与验收条件</label><textarea id="workflow-goal-description" v-model="draftDescription" maxlength="8000" :disabled="draftFrozen"/>
   <details><summary>高级设置：业务类型</summary><label for="workflow-business-type">业务类型</label><select id="workflow-business-type" v-model="draftBusinessType" :disabled="draftFrozen" @change="changeDraftType"><option v-for="type in businessTypes" :key="type.id" :value="type.id">{{ type.label }}</option></select></details>
   <label for="workflow-goal-project">具体工程</label><select id="workflow-goal-project" v-model="draftProjectId" :disabled="draftFrozen" @change="changeDraftProject"><option value="" disabled>请选择已登记的具体工程</option><option v-for="project in draftProjects" :key="project.id" :value="project.id">{{ project.name }}</option></select><p v-if="!draftProjects.length">此分类尚无可关联工程。工程关联不等于获准执行。</p>
   <label for="workflow-delivery-mode">交付方式</label><select id="workflow-delivery-mode" v-model="draftDeliveryMode" :disabled="draftFrozen" required><option value="" disabled>请选择交付方式</option><option value="sample">独立样例</option><option value="source-patch">源码补丁</option></select><p>源码补丁需后端核验指定源码与版本的授权；选择此项不会授予源码读取或工程写入权限。样例不修改工程。</p><p v-if="draftFrozen&&!draftDeliveryMode">原请求未记录交付方式，保留原回执，不重新提交。</p>
   <section v-if="retainedCreates.length" aria-label="保留的创建请求"><p>其他未确认创建保留原标识，不重新提交。</p><button v-for="r in retainedCreates" :key="r.operationId" type="button" :disabled="createSubmitting" @click="selectRetainedCreate(r.operationId)">查看原创建 {{ r.operationId }}</button></section>
   <p>保存只登记草稿，不规划、不启动执行；执行仍须逐任务审阅并满足工程与资源准入。</p>
   <p v-if="createError" role="alert">{{ createError }}</p><p v-if="createNotice" role="status">{{ createNotice }}</p><p v-if="createReceipt">原创建请求：{{ createReceipt.operationId }} · {{ createReceipt.phase }}<span v-if="createReceipt.workflowId"> · {{ createReceipt.workflowId }}</span></p>
   <button v-if="sameDraftPending" type="button" :disabled="createSubmitting" @click="queryGoalDraft">查询原创建回执</button>

   <button v-if="createReceipt" type="button" :disabled="createSubmitting" @click="freshGoalDraft">另建不同目标（保留原回执）</button>
  </form><template #footer><el-button :disabled="createSubmitting" @click="creating=false">取消</el-button><el-button native-type="submit" form="workflow-goal-form" type="primary" :disabled="draftFrozen||!draftOperationId||!draftDeliveryMode||!draftTitle.trim()||!draftProjects.some(p=>p.id===draftProjectId&&p.businessTypes?.includes(draftBusinessType))">保存目标</el-button></template></el-dialog>
  <WorkflowPlanTasks v-if="section==='tasks'" :provider="provider" :records="records" :project-filter="projectFilter" :selected-id="selectedId" :projects="projects??[]" :storage="storage()" :blocked="locked" @select="selectPlanTask" @changed="refresh" />
  <section v-if="section!=='tasks'" aria-label="工作流目标列表" class="workflow-ledger-list">
   <div class="workflow-ledger-filters"><label>搜索<input v-model="listQuery" placeholder="名称或标识"></label><label>状态<select v-model="listState"><option value="">全部状态</option><option v-for="(label,state) in operationLabels" :key="state" :value="state">{{ label }}</option></select></label></div>
   <table><thead><tr><th>选择</th><th>名称</th><th>状态</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in pagedRecords" :key="item.id"><td><input v-model="selectedBatch" type="checkbox" :value="item.id" :disabled="!trashView&&deletionBlocked(item)" :aria-label="`选择 ${item.presentation?.title||item.id}`"><small v-if="!trashView&&deletionBlocked(item)">运行或结果待核对，不能删除</small></td><td>{{ item.presentation?.title||item.id }}</td><td>{{ stateLabel(item) }}</td><td><WorkflowUpdatedAt :value="item.updatedAt??item.createdAt" /></td><td><button type="button" :aria-current="item.id===selectedId?'true':undefined" :data-workflow-id="item.id" @click="select(item.id)">查看详情</button></td></tr><tr v-if="!pagedRecords.length"><td colspan="5">当前筛选下没有记录。</td></tr></tbody></table>
   <el-pagination v-model:current-page="listPage" v-model:page-size="listPageSize" :page-sizes="[10,20,50]" :total="filteredRecords.length" layout="total, sizes, prev, pager, next" />
  </section>
  <WorkflowManagement :provider="provider" :records="records" :selected-id="selectedId" :selected-ids="selectedBatch" :trash-view="trashView" :storage="storage()" :busy="!!busy" @view="trashView=$event;selectedId=''" @locked="managementLocked=$event" @selected="selectedBatch=$event" @record="records=records.map(r=>r.id===$event.id?$event:r)" @purged="records=records.filter(r=>r.id!==$event);if(selectedId===$event)selectedId=''" />
  <div class="operation-columns">
  <article v-if="record"><section v-if="section==='tasks'" aria-label="任务进度与下一步"><h3>任务进度与下一步</h3><p v-if="viewedPlanTaskId">已选择当前计划中的任务；执行与验收以该任务对应记录为准。</p><p>当前：{{ stateLabel(record) }}</p><p v-if="record.state==='unknown'">阻塞原因：结果待核对，请先查询原请求；不会自动重发。</p><p v-else-if="record.state==='failed'">阻塞原因：执行失败，请查看执行详情。</p><p v-else-if="record.state==='paused'">阻塞原因：执行已暂停，需要重新核对依赖。</p><p v-else-if="isStale(record)">阻塞原因：状态读取失败，需要重新核对。</p><p v-else>以当前记录和后端核验结果为准。</p><button v-if="pending" type="button" :disabled="!!busy" @click="reconcile">建议：查询原请求</button><button v-else-if="isStale(record)" type="button" :disabled="!!busy" @click="refresh">建议：读取最新状态</button><button v-else-if="record.state==='draft'" type="button" :disabled="recordLocked" @click="plan">建议：生成计划</button><button v-else-if="['review','ready','paused'].includes(record.state)" type="button" @click="selectRecordTab('specs')">建议：核对计划与依赖</button><button v-else-if="['completed','accepted'].includes(record.state)" type="button" @click="selectRecordTab('acceptance')">建议：核对交付与验收</button><button v-else type="button" @click="selectRecordTab('execution')">建议：查看执行状态</button></section><nav v-if="section==='tasks'" class="record-detail-tabs" aria-label="执行任务详情标签"><button v-for="tab in recordTabs" :key="tab.id" type="button" :data-record-tab="tab.id" :aria-pressed="recordTab===tab.id" @click="selectRecordTab(tab.id)">{{ tab.label }}</button></nav><p v-if="section==='tasks' && formalRun?.taskWorkspace" class="metadata" aria-label="任务目录范围">本次任务目录：{{ formalRun.taskWorkspace.relativePath }}<br>基线 {{ formalRun.taskWorkspace.baselineDigest }}<br>策略 {{ formalRun.taskWorkspace.policyDigest }}；仅本任务目录，不代表整仓库权限。</p><details><summary>技术详情</summary><p class="metadata" data-testid="record-workflow-id">{{ record.id }}</p></details><h3>{{ record.presentation?.title||record.id }}</h3><p class="metadata">交付方式：{{ record.deliveryMode==='sample'?'独立样例':record.deliveryMode==='source-patch'?'源码补丁':'未分类（历史记录）' }}</p><details v-if="showSection('goals','specs') && record.deliveryMode==='source-patch' && record.activeRunId===null && !record.runs.length && ['draft','review','ready'].includes(record.state)" aria-label="源码策略与授权"><summary>源码范围与权限（技术详情）</summary><h4>源码范围</h4><p>先读取服务端策略及绑定状态。授权不会开放工程写入；提交后当前计划和审阅将失效，需要重新规划。</p><p v-if="record.sourceGrant">记录的授权：{{ record.sourceGrant.policyId }} · {{ record.sourceGrant.policyDigest }}；仍需读取当前绑定核验。</p><button type="button" :disabled="!provider.readSourcePolicies||locked||isStale(record)" @click="readSourcePolicies">读取源码策略与绑定</button><p v-if="sourcePolicyError" role="alert">{{ sourcePolicyError }}</p><template v-if="sourcePolicies"><p v-if="!policiesBound" role="status">目标状态已变化，请重新读取策略。</p><template v-else><div v-if="sourcePolicies.binding.state==='static'||sourcePolicies.binding.state==='dynamic'"><p>后端本次已核验{{ sourcePolicies.binding.state==='static'?'静态':'动态' }}源码绑定；规划时仍会重新核验，不需重复授权。</p><p v-if="sourcePolicies.binding.state==='dynamic'&&canChangeSourceGrant">如需更换，请选择不同策略；当前计划和审阅将失效，需要重新规划，历史记录保留。</p><p v-if="sourcePolicies.binding.state==='dynamic'&&!canChangeSourceGrant" role="alert">当前记录与已核验绑定不一致，不能更换，请重新核对。</p><ul><li v-for="f in sourcePolicies.binding.files" :key="f.id">{{ f.id }} · {{ f.root }} · {{ f.path }} · {{ f.sha256 }}</li></ul></div><p v-else-if="sourcePolicies.binding.state==='conflict'||sourcePolicies.binding.state==='unverified'" role="alert">{{ sourcePolicies.binding.state==='conflict'?'源码绑定冲突':'源码绑定未核验' }}；不能据此授权或规划，请核对后端状态。<span v-if="sourcePolicies.binding.reason">（{{ sourcePolicies.binding.reason }}）</span></p><template v-else><p v-if="record.sourceGrant" role="alert">记录中有授权，但本次未发现有效绑定；请核对后端状态，不能重复授权。</p></template><template v-if="canChangeSourceGrant"><p v-if="!availableSourcePolicies.length">当前没有其他可用的源码策略。</p><label v-for="p in availableSourcePolicies" :key="p.id"><input type="radio" name="workflow-source-policy" :value="p.id" v-model="sourcePolicyId" :disabled="locked" @change="sourcePolicyAgreed=false">{{ p.id }} · {{ p.policyDigest }}</label><div v-if="chosenSourcePolicy"><p>将读取以下服务端固定文件（路径及摘要）：</p><ul><li v-for="f in chosenSourcePolicy.files" :key="f.id">{{ f.id }} · {{ f.root }} · {{ f.path }} · {{ f.sha256 }}</li></ul><label><input type="checkbox" v-model="sourcePolicyAgreed" :disabled="locked">我已核对上述文件范围和策略摘要，并确认当前计划和审阅将失效，需要重新规划。</label><button type="button" :disabled="!provider.grantSourcePolicy||locked||isStale(record)||!sourcePolicyAgreed||independentSelected||followupSelected" @click="grantSourcePolicy">{{ sourcePolicies.binding.state==='dynamic'?'确认更换源码范围':'确认授权此源码范围' }}</button></div></template></template></template></details><section v-if="showSection('goals','specs') && !record.deliveryMode && record.activeRunId===null && !record.runs.length && ['draft','review','ready'].includes(record.state)" aria-label="设置历史目标交付方式"><h4>设置历史目标交付方式</h4><p>设置后当前计划和审阅将失效，需要重新规划；历史记录由后端保留。选择源码补丁不会授予源码读取或工程写入权限。</p><p v-if="!provider.changeDeliveryMode">当前服务未提供此操作，请先核对服务版本。</p><label for="workflow-migration-mode">交付方式</label><select id="workflow-migration-mode" v-model="migrationMode" :disabled="locked||isStale(record)"><option value="" disabled>请选择交付方式</option><option value="sample">独立样例</option><option value="source-patch">源码补丁</option></select><label><input type="checkbox" v-model="migrationAgreed" :disabled="locked||isStale(record)">我已了解当前计划和审阅将失效</label><button type="button" :disabled="!provider.changeDeliveryMode||locked||isStale(record)||!migrationMode||!migrationAgreed||independentSelected||followupSelected" @click="migrateDeliveryMode">设置交付方式</button></section><p v-if="record.presentation?.description">{{ record.presentation.description }}</p><el-tag class="companion-status-tag" :type="isStale(record)?'warning':tone(displayedState(record))"><el-icon class="companion-status-icon" :class="{'is-loading':!isStale(record)&&['running','planning'].includes(displayedState(record))}"><Warning v-if="isStale(record)||displayedState(record)==='unknown'"/><Loading v-else-if="['running','planning'].includes(displayedState(record))"/><CircleClose v-else-if="record.state==='failed'"/><CircleCheck v-else-if="record.state==='accepted'"/><InfoFilled v-else/></el-icon>{{ stateLabel(record) }}</el-tag><details><summary>目标技术信息</summary><p class="metadata">GSD · {{ record.goal.ref }} · {{ record.goal.digest }}<br>目标版本 {{ record.goal.version??'来源未提供' }} · 记录 revision {{ record.revision }}</p></details>
   <section v-if="showSection('goals','specs','tasks')" aria-label="计划与审阅"><h4>计划与审阅</h4><template v-if="record.plan"><details><summary>计划标识（技术详情）</summary><p class="metadata">OpenSpec · {{ record.plan.ref }} · {{ record.plan.digest }} · {{ record.plan.version??'来源版本未提供' }}</p></details><template v-if="showSection('goals','specs')"><details v-if="record.presentation?.planText"><summary>完整计划（技术详情）</summary><pre data-testid="full-plan">{{ record.presentation.planText }}</pre></details><p v-else>计划正文尚未读取，不能据摘要批准。</p></template><p v-else>完整计划仅在「规格」分区展示；此处保留任务及依赖审阅，不重复计划正文。</p></template><p v-else>尚无计划；不会自动启动执行。</p><details v-if="record.plan" aria-label="任务与来源审阅"><summary>任务与来源审阅（技术详情）</summary><h5>任务与来源审阅</h5><p v-if="record.state==='paused'">只可重新核对原已选任务的依赖；不会更换任务、会话或自动恢复。</p><p v-if="record.state==='paused'&&!record.review?.readiness?.selectedTaskId">该历史执行未记录原任务绑定，不能推测新的审阅目标。</p><el-button :disabled="!!busy||!provider.readReadiness" @click="readReadiness">读取审阅目录</el-button><p v-if="!provider.readReadiness">审阅目录未接通，来源就绪未验证，不能启动。</p><p v-if="readinessError" role="status">{{ readinessError }}</p><p v-if="readinessNotice" role="status">{{ readinessNotice }}</p><p v-if="readinessStale">上次审阅目录观察 · 当前待核对</p><p v-if="!readiness">尚未读取真实任务与来源；不能用计划勾选代替就绪证据。</p><template v-else><p v-if="!readinessBound" role="status">目标或计划版本已变化，请先读取最新状态后重新核对。</p><p v-if="readiness.availability==='unconfigured'" role="status">来源政策未配置，不能审阅或启动。</p><p v-if="readiness.currentStatus==='stale'" role="status">已保存的审阅来源已变化或过期，不能继续使用。</p><label for="workflow-review-task">选择计划中的真实任务</label><select id="workflow-review-task" :value="selectedTaskId" :disabled="recordLocked||!readinessBound||readinessStale||!['review','paused'].includes(record.state)" @change="chooseReadinessTask(($event.target as HTMLSelectElement).value)"><option value="">选择任务</option><option v-for="task in readiness.tasks" :key="task.id" :value="task.id" :disabled="record.state==='paused'&&task.id!==record.review?.readiness?.selectedTaskId">{{ task.id }} · {{ task.text }}</option></select><template v-if="selectedTask"><p>{{ selectedTask.text }}</p><small>任务摘要 {{ selectedTask.digest }} · tasks.md 摘要 {{ selectedTask.artifactDigest }}</small><p v-if="selectedTask.requiredDependencies===null">该任务依赖未配置，不能审阅。</p><p v-else>必需依赖：{{ selectedTask.requiredDependencies.join('、') }}</p><fieldset><legend>选择后端核验的来源</legend><label v-for="source in readiness.sources.filter(s=>s.taskId===null||s.taskId===selectedTaskId)" :key="source.id" class="evidence-row"><input type="checkbox" :checked="selectedSourceIds.includes(source.id)" :disabled="recordLocked||readinessStale||!readinessBound||!sourceSelectable(source)||!['review','paused'].includes(record.state)" @change="chooseReadinessSource(source,($event.target as HTMLInputElement).checked)"><span>{{ source.label }} · {{ source.status==='verified'?'后端已核验':'受阻' }}<small>{{ source.id }} · {{ source.digest }}</small><small>有效期 {{ source.expiresAt??'未确认' }}<span v-if="source.expiresAt&&Date.parse(source.expiresAt)<=approvalClock"> · 已过期</span></small><small>解决：{{ source.resolves.join('、')||'无' }} · 剩余：{{ source.remaining.join('、')||'无' }}</small><small v-if="source.reason">原因：{{ source.reason }}</small></span></label></fieldset><p v-if="unresolvedDependencies.length">尚缺依赖：{{ unresolvedDependencies.join('、') }}</p><div v-if="record.deliveryMode==='source-patch'"><p>源码补丁目标范围需先核对，当前显示的是后端提供的目标路径与文件摘要。</p><button type="button" :disabled="!!busy||!provider.readSourcePolicies" @click="readSourcePolicies">读取补丁目标范围</button><template v-if="policiesBound&&sourcePolicies?.patchPolicy"><p>{{ sourcePolicies.patchPolicy.targetRoot }} · {{ sourcePolicies.patchPolicy.policyDigest }}</p><ul><li v-for="f in sourcePolicies.patchPolicy.files" :key="f.id">{{ f.path }} · {{ f.sha256 }}</li></ul></template><p v-else>目标范围未核验，不能审阅源码补丁计划。</p></div><label for="workflow-review-note">审阅备注</label><textarea id="workflow-review-note" v-model="reviewNote" maxlength="2000" :disabled="recordLocked||!['review','paused'].includes(record.state)"/><p>身份由后端认证；此处不接收项目 Owner 声明、路径或就绪勾选。</p></template><details v-if="readiness.current"><summary>已保存的不可变审阅记录</summary><dl><dt>记录</dt><dd>{{ readiness.current.id }} · v{{ readiness.current.version }}</dd><dt>来源</dt><dd>{{ readiness.current.ref }}</dd><dt>摘要</dt><dd>{{ readiness.current.digest }}</dd><dt>任务</dt><dd>{{ readiness.current.selectedTaskId }}</dd><dt>有效期</dt><dd>{{ readiness.current.expiresAt }}<span v-if="Date.parse(readiness.current.expiresAt)<=approvalClock"> · 已过期</span></dd><dt>状态</dt><dd>{{ readiness.currentStatus==='fresh'?'后端当前核验有效':readiness.currentStatus==='stale'?'来源变化 / 已失效':'未核验' }}</dd><dt>审阅身份</dt><dd>{{ readiness.current.actor.kind==='isolated-control-harness'?'隔离控制样例（非浏览器登录）':'后端认证主体，不等于项目 Owner 声明' }}</dd></dl></details></template></details><div class="commands"><el-button v-if="['draft','review','ready'].includes(record.state)" :disabled="recordLocked" @click="plan">生成计划</el-button><el-button v-if="record.state==='planning'||record.state==='unknown'&&!record.runs.length&&record.planningConversation?.requestId" :disabled="!!busy" @click="readExecution">查询规划状态</el-button><el-button v-if="['planning','unknown'].includes(record.state)&&provider.listRequestIngress&&!pending" :disabled="!!busy||pendingCorrupt" @click="findServerRequest">查找原请求</el-button><el-button v-if="['review','paused'].includes(record.state)" :disabled="!canReview||!record.plan||!record.presentation?.planText" @click="review">{{ record.state==='paused'?'重新审阅原任务依赖':'审阅并批准此版本计划' }}</el-button><el-button v-if="record.state==='ready'" type="primary" :disabled="recordLocked||!canStart(record)||!readinessProofCurrent" @click="start">启动执行</el-button></div></section>
   <details v-if="record.plan && record.planningConversation?.requestId && provider.recoverPlanningTransport"><summary>规划连接恢复（技术详情）</summary><p>仅核查原规划在系统重启后的连接状态，保留原记录和预算；不会重新规划。核查不通过时继续保留待确认状态。</p><el-button :disabled="!!busy" @click="recoverPlanningTransport">核查原规划连接</el-button><p v-if="planningRecoveryMessage" role="status">{{ planningRecoveryMessage }}</p></details>
   <ConversationIdentity v-if="showSection('specs','execution','evidence') && record.planningConversation" :workflow-id="record.id" :conversation="record.planningConversation" :workflow-state="record.state" phase="planning" />
<ConversationIdentity v-if="showSection('execution','evidence') && run" :workflow-id="record.id" :conversation="run.conversation" :known-thread-id="run.executionId" :request-id="run.operationId" :workflow-state="record.state" phase="execution" />
<section v-if="showSection('execution','evidence')" aria-label="执行与回执"><h4>执行与回执</h4><p v-if="run">执行标识：{{ run.executionId??'尚未确认' }} · {{ run.lastObservedAt }}</p><p v-if="run?.reason">{{ run.reason }}</p><p v-if="record.state==='starting'">启动请求已受理，真实执行标识尚待确认。</p><div class="commands"><el-button :disabled="!!busy" @click="readExecution">查询执行与证据</el-button><el-button v-if="record.state==='unknown'&&provider.readRecoveryPreflight" :disabled="!!busy" @click="readRecoveryPreflight">读取恢复条件（不处置）</el-button><el-button v-if="record.state==='unknown'&&provider.abandonBeforeTurn" :disabled="!!busy||isStale(record)||!recoveryPreview?.canRequestVerification||recoveryPreview.revision!==record.revision" @click="abandonBeforeTurn">核对未派发并放弃</el-button><span v-if="record.state==='unknown'">仅服务端证据全部核实后追加放弃；不重发任务，原 UNKNOWN 审计保留。</span><el-button v-if="['running','queued'].includes(displayedState(record))" :disabled="recordLocked||!run?.executionId" @click="pause">请求安全边界暂停</el-button><el-button v-if="record.state==='paused'" :disabled="locked||!readinessProofCurrent" @click="resume">核对状态并恢复</el-button></div><section v-if="record.state==='unknown'" aria-label="恢复证据预检"><p>先读取本地证据条件；缺证时不能放弃。预检不会加载线程或调用模型，也不证明当前可安全处置。</p><p v-if="recoveryPreviewError" role="alert">{{ recoveryPreviewError }}</p><template v-if="recoveryPreview"><p>本地记录观察：{{ recoveryPreview.observedAt }} · 目标 revision {{ recoveryPreview.revision }}</p><ul><li v-for="check in recoveryPreview.checks" :key="check.id"><strong>{{ check.status==='missing'?'缺少证据':check.status==='unverified'?'尚未核实':'历史记录' }}</strong>：{{ check.message }}</li></ul><p v-if="!recoveryPreview.canRequestVerification" role="status">当前缺少必要记录，处置按钮已禁用；原 UNKNOWN 保留。</p><p v-else role="status">本地必要记录齐备；请求完整核对仍由原服务端严格重查，当前未证明可放弃。</p></template></section><p v-if="['running','queued','pause-requested','paused'].includes(record.state)">暂停等待执行器的安全边界回执，不承诺立即取消。恢复先核对原执行标识。</p>
   <ul aria-label="日志引用"><li v-for="log in details?.logs??[]" :key="log.ref"><strong>{{ log.ref }}</strong><p>{{ log.summary??'仅有引用，正文尚未读取' }}</p><small>{{ log.digest }} {{ log.at }}</small></li></ul><ul v-if="!details?.logs?.length&&run?.logRefs.length"><li v-for="ref in run.logRefs" :key="ref">{{ ref }} · 日志引用，正文未读取</li></ul></section>
   <section v-if="showSection('execution')" aria-label="当前会话审批"><h4>当前会话审批</h4><p class="metadata">只处理原会话本次待决请求，不授予整段会话权限；任务写入范围由后端验证，本页没有整段会话或仓库权限开关。</p><el-button :disabled="!!busy||!provider.readApprovals" @click="readApprovals">读取当前会话审批</el-button><p v-if="!provider.readApprovals">审批适配器未接通，能力未验证。</p><p v-if="approvalError" role="status">{{ approvalError }}</p><p v-if="approvalsStale">上次审批观察 · 当前待核对，不能批准或重发。</p><p v-if="approvals===null">尚未读取真实待决请求；不能据此认定没有审批。</p><template v-else><p v-if="!approvals.enabled">审批能力未启用。不能据此认定没有待决请求。</p><p v-else-if="!approvals.approvals.length">本次读取未见待决请求。后续连接状态仍需重新核对。</p><p class="metadata">观察时间 {{ approvals.observedAt }}</p><article v-for="a in approvals.approvals" :key="a.id" class="approval-entry"><h5>{{ a.kind==='command'?'命令请求':'文件变更请求' }} · {{ approvalStateLabels[a.state] }}</h5><p>{{ a.summary }}</p><pre v-if="a.display.command">{{ a.display.command }}</pre><ul v-if="a.display.relativePaths?.length"><li v-for="path in a.display.relativePaths" :key="path">{{ path }}</li></ul><dl><dt>请求 / 版本</dt><dd>{{ a.id }} / {{ a.version }}</dd><dt>摘要</dt><dd>{{ a.approvalDigest }}</dd><dt>原始来源</dt><dd>{{ a.threadId }} / {{ a.turnId }} / {{ a.itemId }}</dd><dt>连接</dt><dd>{{ a.connectionId }} · {{ a.state==='disconnected'?'已断线':a.canRespond&&a.state==='pending'?'原连接报告可响应':'当前不可响应' }}</dd><dt>有效期</dt><dd>{{ a.expiresAt }}<strong v-if="Date.parse(a.expiresAt)<=approvalClock"> · 已过期，不能响应</strong></dd></dl><div class="commands"><el-button :disabled="!approvalActionable(a)||!provider.decideApproval" @click="decideApproval(a,'accept')">仅本次批准</el-button><el-button :disabled="!approvalActionable(a)||!provider.decideApproval" @click="decideApproval(a,'decline')">拒绝本次请求</el-button></div></article></template></section>
   <section v-if="showSection('evidence')" aria-label="准备调用证据"><h4>知识库与角色准备证据</h4><el-button :disabled="!!busy||!provider.readPreparation" @click="readPreparation">读取准备调用证据</el-button><p v-if="!provider.readPreparation">当前适配器未提供准备证据读取，未验证。</p><p v-if="preparationError" role="status">{{ preparationError }}</p><p v-if="preparationStale">上次观察 · 当前待核对</p><p v-if="preparation===null">按需读取关联标识和摘要，不读取知识库正文。</p><p v-else-if="!preparation.length">暂无已保存的准备调用证据；不据此认定已使用预设。</p><details v-for="entry in preparation??[]" :key="entry.operationId" class="preparation-entry"><summary>{{ entry.evidence.phase }} · {{ preparationStateLabels[entry.state] }} · {{ entry.operationId }}</summary><p>{{ preparationMatches(entry)?'与当前目标版本关联':'历史或不匹配版本，不能作为当前阶段通过证据' }}<span v-if="entry.evidence.planDigest===null"> · 计划生成前取证</span></p><p>本地 wrapper 关联与检索结果已记录，不证明模型采用或业务完成。</p><dl><dt>调用证据</dt><dd>{{ entry.evidence.evidenceRef }}</dd><dt>目标摘要</dt><dd>{{ entry.evidence.goalDigest }}</dd><dt>计划摘要</dt><dd>{{ entry.evidence.planDigest??'尚未生成计划' }}</dd><dt>知识库结果</dt><dd>{{ entry.evidence.kb.status==='hit'?'命中':'零命中' }}</dd><dt>请求 / 响应</dt><dd>{{ entry.evidence.kb.requestId }} / {{ entry.evidence.kb.responseId }}</dd><dt>查询摘要</dt><dd>{{ entry.evidence.kb.queryDigest }}</dd></dl><ul><li v-for="role in entry.evidence.roles" :key="role.id">{{ role.id }} · {{ roleModeLabels[role.mode] }}<small>{{ role.configDigest }} · {{ role.evidenceRef }}</small></li></ul><ul><li v-for="doc in entry.evidence.kb.documents" :key="doc.id">{{ doc.id }} · {{ doc.version??'版本未提供' }}<small>{{ doc.digest }}</small></li></ul></details></section>
   <WorkflowDelivery v-if="showSection('acceptance')&&record.deliveryMode==='source-patch'" :key="record.id" :provider="provider" :record="record" :blocked="recordLocked" :storage="storage()" />
   <section v-if="showSection('acceptance')" aria-label="验收证据"><h4>{{ acceptanceScope==='task-directory'?'任务目录验收':acceptanceScope==='technical-sample'?'技术样例验收':'执行范围待核对' }}</h4><p>任务勾选、自动测试和真实业务验收分别核对；按钮不会把缺失证据改成通过。</p><div v-if="record.deliveryMode==='source-patch'" data-testid="source-patch-status"><p>补丁检查：{{ patchInspectionCurrent?'本次检查通过（提交时后端将再次核验）':patchInspectionError||'未核验或已过期' }}。</p><button type="button" :disabled="!!busy||record.state!=='completed'" @click="readPatchInspection">重新检查源码补丁</button><p v-if="patchInspectionCurrent&&patchInspection">检查时间 {{ patchInspection.observedAt }} · 补丁摘要 {{ patchInspection.patchDigest }} · 策略摘要 {{ patchInspection.policyDigest }}</p><p v-if="run?.acceptance?.patchInspection">任务目录验收前的历史检查时间 {{ run.acceptance.patchInspection.observedAt }}；这是当时快照，不能证明当前状态。</p><p>实际测试：未核验。</p><p>工程应用：未确认。</p><p>执行活动：未核验；应用前需再次检查。</p><p>任务目录验收只记录范围内结果，不代表产品已验收或工程已应用。</p></div><label v-for="e in details?.evidence??[]" :key="e.ref" class="evidence-row"><input v-model="selectedEvidence" type="checkbox" :value="e.digest" :disabled="recordLocked||record.state!=='completed'"><span>{{ e.ref }} · {{ e.kind }} · {{ e.state }}<small>{{ e.digest }}</small>{{ e.summary }}</span></label><p v-if="!details?.evidence?.length">尚无可核对的证据内容。</p><template v-if="record.state==='completed'&&acceptanceScope!=='unverified'"><label for="workflow-acceptance-note">本次验收结论与依据</label><textarea id="workflow-acceptance-note" v-model="acceptanceNote" maxlength="4000" :disabled="recordLocked"/><el-button :disabled="recordLocked||(record.deliveryMode==='source-patch'&&!patchInspectionCurrent)||!acceptanceNote.trim()||!selectedEvidence.length" @click="accept">{{ acceptanceScope==='task-directory'?'提交任务目录验收':'提交技术样例验收' }}</el-button></template></section>
  </article><p v-else-if="records.length">选择一个目标查看计划、执行和验收。</p></div>
 </section>
</template>
