}.evidence-row{display:flex;gap:8px;margin:10px 0;align-items:flex-start}.evidence-row span{overflow-wrap:anywhere}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:2px solid var(--el-color-primary);outline-offset:2px}@media(max-width:760px){.operation-columns{grid-template-columns:1fr}.operation-columns nav{display:flex;overflow:auto;gap:8px}.operation-columns nav button{min-width:190px}.commands{align-items:stretch}.commands .el-button{margin-left:0}article>section{padding:12px}}
